using System.Text.Json.Serialization;

namespace IAuto.HybridIntegration.Functions.Models;

/// <summary>Structured response returned to API Management and the Logic Apps Standard workflow.</summary>
public sealed record BusinessEventResponse
{
    /// <summary>Event identifier used for idempotency and downstream correlation.</summary>
    [JsonPropertyName("eventId")]
    public required string EventId { get; init; }

    /// <summary>Correlation identifier from the caller or generated by the bridge.</summary>
    [JsonPropertyName("correlationId")]
    public required string CorrelationId { get; init; }

    /// <summary>Whether the bridge accepted and enriched the event.</summary>
    [JsonPropertyName("accepted")]
    public bool Accepted { get; init; }

    /// <summary>AI-assisted enrichment summary from the shared inference module.</summary>
    [JsonPropertyName("enrichment")]
    public required EventEnrichment Enrichment { get; init; }

    /// <summary>Deterministic routing decision used by the orchestration branch.</summary>
    [JsonPropertyName("routing")]
    public required RoutingDecision Routing { get; init; }
}

/// <summary>Inference output normalized for downstream workflow steps.</summary>
public sealed record EventEnrichment
{
    /// <summary>Concise business summary suitable for approvals and audit trails.</summary>
    [JsonPropertyName("summary")]
    public required string Summary { get; init; }

    /// <summary>Model identifier selected by the shared inference configuration.</summary>
    [JsonPropertyName("model")]
    public required string Model { get; init; }
}

/// <summary>Routing information computed by the bridge after enrichment.</summary>
public sealed record RoutingDecision
{
    /// <summary>Priority used by the Logic Apps Standard branch.</summary>
    [JsonPropertyName("priority")]
    public required string Priority { get; init; }

    /// <summary>Queue, team, or API path that should handle the event next.</summary>
    [JsonPropertyName("target")]
    public required string Target { get; init; }

    /// <summary>Human-readable explanation of the routing decision.</summary>
    [JsonPropertyName("reason")]
    public required string Reason { get; init; }
}
